export const BRAINSTORMING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu brainstorming",q:"'Brainstorming' (curah gagasan) adalah...",options:["Kegiatan menghasilkan sebanyak mungkin ide untuk sebuah masalah, tanpa buru-buru menilai","Kegiatan memilih satu jawaban paling benar lalu menolak gagasan lain yang muncul","Kegiatan berdebat panjang untuk menentukan siapa di antara anggota yang paling pintar"],answer:0,explain:"Tujuan brainstorming adalah banyaknya ide dulu. Menyaring & menilai dilakukan di tahap berikutnya, terpisah.",hint:"Menghasilkan banyak ide, atau memilih satu jawaban benar?"},
{n:2,type:"mcq",micro:"Tunda penilaian",q:"Aturan penting saat curah gagasan:",options:["Hanya boleh menyebut ide yang sudah berhasil supaya waktu kelompok tak terbuang percuma","Tunda kritik dulu — jangan langsung bilang 'itu tidak mungkin' saat ide masih muncul","Kritik setiap ide saat itu juga supaya ide lemah tidak menghabiskan waktu kelompok"],answer:1,explain:"Kritik dini membuat orang takut berbicara & aliran ide berhenti. Kritik penting, tapi belakangan.",hint:"Tunda kritik, atau kritik segera?"},
{n:3,type:"mcq",micro:"Kuantitas dulu",q:"Kenapa saat brainstorming kita mengejar JUMLAH ide dulu?",options:["Karena jumlah ide lebih penting daripada mutunya dalam segala hal","Supaya kelompok terlihat sibuk dan rajin di depan guru yang mengamati","Makin banyak ide, makin besar peluang ada ide bagus di antaranya"],answer:2,explain:"Ide bagus jarang muncul pertama. Dari 30 ide, mungkin 2-3 yang layak dikembangkan, tapi kita butuh 30 dulu.",hint:"Banyak ide = peluang lebih besar, atau sekadar terlihat sibuk?"},
{n:4,type:"mcq",micro:"Ide liar diterima",q:"Saat ada yang menyebut ide yang terdengar aneh atau mustahil, sebaiknya...",options:["Terima & catat — ide liar sering jadi batu loncatan ke ide yang bisa dipakai","Langsung tertawakan supaya ide liar tidak mengganggu jalannya sesi","Larang menyebut ide seperti itu karena sesi harus berisi ide masuk akal"],answer:0,explain:"'Rumah terbang' mungkin mustahil, tapi bisa memancing ide 'rumah yang mudah dipindah'. Ide liar punya benih.",hint:"Terima sebagai batu loncatan, atau tertawakan?"},
{n:5,type:"mcq",micro:"Membangun ide orang lain",q:"Cara sehat menanggapi ide teman saat curah gagasan:",options:["Diam saja menunggu giliran sampai ide sendiri siap dikatakan","'Ya, dan kita bisa tambahkan...' — membangun di atas idenya","'Ya, tapi itu tidak akan jalan, lebih baik cari ide lain.'"],answer:1,explain:"'Ya, dan' menyambung & memperkaya. Ide sering jadi bagus setelah beberapa orang menambahinya.",hint:"Membangun di atasnya, atau langsung mematahkan?"},
{n:6,type:"mcq",micro:"Mencatat semua ide",q:"Kenapa penting menuliskan setiap ide yang muncul?",options:["Supaya bisa dinilai cepat siapa yang idenya paling salah dan tak berguna","Tidak penting, karena ide yang bagus akan diingat sendiri oleh anggota kelompok","Supaya tidak hilang & bisa dilihat semua orang, sehingga memicu ide berikutnya"],answer:2,explain:"Ide yang terlihat (di papan/kertas) memancing ide lain. Ide yang tidak dicatat sering lenyap.",hint:"Terlihat & memicu ide lain, atau pasti teringat?"},
{n:7,type:"mcq",micro:"Fokus pada satu masalah",q:"Sebelum curah gagasan dimulai, hal yang perlu jelas:",options:["Masalah atau pertanyaan yang sedang kita pecahkan, dalam satu kalimat","Siapa yang menjadi pemimpin kelompok dan siapa yang cukup mendengarkan saja","Berapa lama waktu istirahat nanti dan makanan apa yang akan dibeli anggota"],answer:0,explain:"Tanpa pertanyaan yang jelas ('Bagaimana caranya kita...'), ide-ide melebar ke mana-mana & tidak berguna.",hint:"Perjelas pertanyaannya, atau tentukan pemimpin?"},
{n:8,type:"mcq",micro:"Semua orang ikut",q:"Dalam curah gagasan kelompok yang baik...",options:["Anggota yang pendiam sebaiknya keluar dulu supaya sesi tidak terganggu oleh orang yang jarang bicara","Setiap orang punya kesempatan menyumbang ide, bukan hanya yang paling berani bicara","Cukup satu-dua orang yang paling pandai bicara saja yang menyumbang ide, sisanya mendengarkan"],answer:1,explain:"Ide terbaik sering datang dari orang yang jarang bicara. Perlu cara agar semua bisa menyumbang.",hint:"Semua kebagian, atau cukup yang berani?"},
{n:9,type:"order",micro:"Alur sesi curah gagasan",q:"Urutkan langkah sesi curah gagasan sederhana.",items:["Tuliskan pertanyaan/masalah dengan jelas di papan","Sepakati aturan: tunda kritik, kejar jumlah, ide liar diterima","Semua menyumbang ide, dicatat tanpa dinilai, selama waktu tertentu","Setelah waktu habis, baru kelompokkan & pilih ide untuk dikembangkan"],answer:[0,1,2,3],explain:"Perjelas masalah → sepakati aturan → hasilkan ide tanpa menilai → baru menilai. Menghasilkan & menilai selalu terpisah.",hint:"Menilai ide di langkah pertama atau terakhir?"},
{n:10,type:"mcq",micro:"'Bagaimana caranya kita'",q:"Mengubah masalah 'Kantin selalu ramai & antre panjang' jadi pertanyaan curah gagasan yang baik:",options:["'Siapa yang salah sehingga antrean kantin panjang?'","'Kenapa kantin ini payah sampai murid berdiri lama?'","'Bagaimana caranya kita mengurangi antrean di kantin?'"],answer:2,explain:"'Bagaimana caranya kita...' mengundang solusi & rasa ikut memiliki. Kalimat menyalahkan menutup ide.",hint:"Mengundang solusi, atau mencari yang disalahkan?"},
{n:11,type:"tf",micro:"Kritik dulu supaya efisien?",q:"Benar atau Salah: Cara paling efisien brainstorming adalah langsung mengkritik setiap ide begitu disebut, supaya tidak buang waktu pada ide jelek.",answer:false,explain:"Sebaliknya, kritik dini membuat orang takut menyumbang & menghentikan aliran ide. Pisahkan waktu menghasilkan ide dari waktu menilainya.",hint:"Kritik segera hemat waktu, atau justru menghentikan ide?"},
{n:12,type:"tf",micro:"Ide jelek berguna",q:"Benar atau Salah: Ide yang 'jelek' atau lucu tetap bisa berguna karena memancing orang lain memikirkan ide yang lebih baik.",answer:true,explain:"Ide konyol sering membuka arah baru. Satu ide 'gila' bisa jadi jembatan ke ide yang benar-benar dipakai.",hint:"Bisa memancing ide lebih baik, atau benar-benar tak berguna?"},
{n:13,type:"mcq",micro:"Menulis ide sendiri dulu",q:"Sebelum berbagi dalam kelompok, meminta setiap orang menulis idenya sendiri selama 2 menit berguna karena...",options:["Mencegah semua orang hanya mengikuti ide pertama yang disebut & memastikan semua punya bahan","Membuat sesi berlangsung lebih lama tanpa alasan jelas bagi anggota yang hadir","Menyembunyikan ide masing-masing dari kelompok supaya tak ada yang bisa meniru atau mengkritik"],answer:0,explain:"Menulis sendiri dulu ('brainwriting') menjaga keragaman ide & memberi ruang bagi yang pemalu.",hint:"Menjaga keragaman ide, atau memperlambat tanpa alasan?"},
{n:14,type:"mcq",micro:"Jumlah target",q:"Menetapkan target seperti 'kita kumpulkan 20 ide dalam 5 menit' membantu karena...",options:["Membatasi kreativitas karena orang hanya mengejar angka, bukan isi ide","Mendorong orang melewati ide-ide biasa & menggali ide yang kurang jelas","Membuat orang stres dan tegang tanpa manfaat bagi hasil sesi kelompok"],answer:1,explain:"Target jumlah memaksa kita tidak berhenti di 3-4 ide pertama yang mudah, tempat ide segar biasanya bersembunyi.",hint:"Mendorong menggali lebih dalam, atau sekadar bikin stres?"},
{n:15,type:"mcq",micro:"Peran pencatat",q:"Dalam sesi kelompok, peran 'pencatat' bertugas...",options:["Memilih ide yang layak dicatat dan membuang yang kurang bagus","Menilai tiap ide sambil menulis lalu mencoret yang tak masuk akal","Menuliskan semua ide dengan cepat & apa adanya, tanpa menyaring"],answer:2,explain:"Pencatat menangkap semuanya. Menyaring saat mencatat = ide hilang sebelum sempat dipertimbangkan.",hint:"Catat semua apa adanya, atau saring sambil menulis?"},
{n:16,type:"tf",micro:"Brainstorming hanya untuk kelompok?",q:"Benar atau Salah: Brainstorming hanya bisa dilakukan dalam kelompok, tidak mungkin sendirian.",answer:false,explain:"Sebaliknya, curah gagasan sendiri juga efektif, bahkan sering menghasilkan lebih banyak ide unik karena tidak ada yang mendominasi. Menggabungkan sesi sendiri lalu kelompok biasanya paling baik.",hint:"Hanya kelompok, atau bisa sendiri juga?"},
{n:17,type:"mcq",micro:"Suasana aman",q:"Suasana yang membuat curah gagasan berjalan lancar:",options:["Aman untuk salah — tidak ada yang ditertawakan atau diremehkan karena idenya","Kompetitif — siapa yang idenya paling dipuji teman dianggap pemenang sesi","Tegang — anggota takut idenya dinilai jelek sehingga memilih tak banyak bicara"],answer:0,explain:"Rasa aman = orang berani menyebut ide setengah jadi. Rasa takut = hanya ide 'aman' yang keluar.",hint:"Aman untuk salah, atau takut dinilai?"},
{n:18,type:"mcq",micro:"Membatasi waktu",q:"Kenapa sesi curah gagasan sebaiknya dibatasi waktunya (mis. 10 menit)?",options:["Waktu tak perlu dibatasi, sebab ide terbaik biasanya muncul setelah berjam-jam berpikir","Batas waktu menjaga energi tinggi & mendorong ide keluar cepat tanpa terlalu dipikir","Supaya sesi cepat selesai dan anggota bisa segera bermain di luar kelas setelah itu"],answer:1,explain:"Tekanan waktu yang wajar membuat orang menyebut ide sebelum sempat menyensornya sendiri.",hint:"Menjaga energi & spontanitas, atau sekadar biar cepat?"},
{n:19,type:"mcq",micro:"Setelah brainstorming",q:"Segera setelah ide-ide terkumpul, langkah berikutnya:",options:["Langsung kerjakan semua ide yang terkumpul sekaligus tanpa memilih mana yang lebih penting","Buang semua ide yang sudah terkumpul lalu mulai lagi dari nol supaya mendapat ide yang baru","Kelompokkan ide yang mirip, lalu pilih beberapa untuk dikembangkan atau diuji"],answer:2,explain:"Curah gagasan menghasilkan bahan mentah. Mengelompokkan & memilih mengubahnya jadi rencana.",hint:"Kelompokkan lalu pilih, atau kerjakan semua sekaligus?"},
{n:20,type:"open",micro:"Latihan kuantitas",q:"Pertanyaan: 'Bagaimana caranya kita membuat perjalanan ke sekolah lebih menyenangkan?' Tulis minimal 12 ide berbeda dalam waktu singkat. Jangan menilai dulu, sertakan yang liar sekalipun. Setelah itu, tandai 2 ide yang menurutmu paling menarik.",explain:"Jawaban baik: minimal 12 ide yang benar-benar berbeda (bukan variasi satu ide), termasuk beberapa yang tidak biasa, lalu 2 pilihan dengan alasan singkat. Yang dinilai adalah kemampuan menghasilkan banyak & beragam, bukan kesempurnaan tiap ide.",hint:"Kalau macet di ide ke-6, ubah sudut: teknologi, teman, permainan, rute, suara, gambar, kebiasaan kecil.",sample:"1. Podcast cerita seru khusus perjalanan pagi. 2. Grup jalan kaki bersama teman satu arah. 3. Permainan 'cari benda' di sepanjang jalan. 4. Rute alternatif lewat taman. 5. Sepeda dihias bersama. 6. Tantangan foto pemandangan tiap hari. 7. Bergantian bercerita di angkot. 8. Peta 'tempat menarik' buatan siswa. 9. Musik pilihan bergiliran. 10. Belajar 3 kata bahasa asing tiap perjalanan. 11. Bus sekolah dengan tema mingguan. 12. Buku sketsa perjalanan. 13. Menyapa penjaga sekolah & satpam sebagai kebiasaan. Ide paling menarik: nomor 2 (grup jalan kaki) karena murah, sehat, & langsung bisa dicoba; dan nomor 8 (peta tempat menarik) karena melibatkan banyak siswa & hasilnya bisa dipakai terus."},
{n:21,type:"classify",micro:"Membantu vs merusak curah gagasan",q:"Kelompokkan tiap perilaku ke 'Membantu curah gagasan' atau 'Merusak curah gagasan'.",items:["'Ide bagus! Bagaimana kalau ditambah begini?'","'Itu ide paling konyol yang pernah kudengar.'","Menuliskan semua ide di papan tanpa menyaring","Menghentikan orang di tengah kalimat untuk membantah"],groups:["Membantu curah gagasan","Merusak curah gagasan"],answer:{"Membantu curah gagasan":["'Ide bagus! Bagaimana kalau ditambah begini?'","Menuliskan semua ide di papan tanpa menyaring"],"Merusak curah gagasan":["'Itu ide paling konyol yang pernah kudengar.'","Menghentikan orang di tengah kalimat untuk membantah"]},explain:"Membantu: membangun ide, mencatat semua. Merusak: mengejek, memotong, menilai terlalu dini.",hint:"Menambah aliran ide, atau menghentikannya?"},
{n:22,type:"mcq",micro:"Kuantitas vs kualitas",q:"Pernyataan yang tepat tentang curah gagasan:",options:["Kejar kuantitas SAAT menghasilkan ide; nilai kualitas SETELAH, di tahap terpisah","Kualitas harus dijaga setiap detik, jadi tolak ide lemah begitu disebutkan teman","Kuantitas tak penting dalam kegiatan ini, yang utama hanya satu ide sempurna"],answer:0,explain:"Dua mode berbeda: 'mode menghasilkan' (banyak, tanpa menilai) & 'mode menilai' (memilih). Dicampur = keduanya rusak.",hint:"Pisah waktu menghasilkan & menilai, atau nilai terus-menerus?"},
{n:23,type:"mcq",micro:"Kenapa ide pertama biasa",q:"Ide-ide pertama yang muncul saat brainstorming cenderung...",options:["Yang paling aneh dan belum pernah dipikirkan siapa saja","Yang paling jelas & sudah pernah dipikirkan banyak orang","Yang terbaik dan sudah dipilih oleh guru sebelum sesi"],answer:1,explain:"Ide 'permukaan' keluar duluan. Ide yang lebih segar butuh digali setelah yang mudah habis.",hint:"Paling jelas & umum, atau paling segar?"},
{n:24,type:"mcq",micro:"Groupthink",q:"'Groupthink' (pikiran seragam) dalam kelompok terjadi ketika...",options:["Kelompok menghasilkan terlalu banyak ide yang berbeda-beda sehingga sulit untuk memilih salah satunya","Ada satu orang yang tidak setuju dengan pendapat kelompok & terus berusaha mengajukan alternatif lain","Semua orang cepat setuju pada satu ide & berhenti mencari alternatif demi menghindari ketegangan"],answer:2,explain:"Groupthink membuat kelompok memilih ide biasa-biasa saja hanya karena terasa 'kompak'. Perbedaan pendapat justru sehat.",hint:"Cepat kompak & berhenti mencari, atau terlalu banyak ide?"},
{n:25,type:"mcq",micro:"Melawan dominasi",q:"Satu orang mendominasi & idenya selalu diikuti. Cara menyeimbangkan:",options:["Pakai ronde giliran atau menulis ide di kertas dulu, sehingga semua suara masuk","Biarkan saja apa adanya, sebab dia paling pintar dan idenya yang terbaik di kelompok","Suruh dia diam selama sesi supaya orang lain bisa bicara tanpa ia ikut campur"],answer:0,explain:"Alat sederhana (giliran, kertas, catatan anonim) membuka ruang bagi ide yang tertutup oleh suara dominan.",hint:"Beri struktur agar semua masuk, atau biarkan didominasi?"},
{n:26,type:"mcq",micro:"Ide liar sebagai jembatan",q:"Seseorang berkata 'bagaimana jika sekolah di dalam air?'. Cara memakainya:",options:["Tertawakan ide itu bersama-sama lalu lanjut ke ide berikutnya, karena sekolah di dalam air jelas tidak masuk akal untuk dibahas","Tanya 'apa yang menarik dari itu?' → mungkin: ruang tenang, suasana baru → ide: ruang belajar yang lebih tenang & berbeda","Coret ide itu dari daftar karena mustahil dan tak ada gunanya bagi sekolah, jadi lebih baik cari ide yang lebih masuk akal"],answer:1,explain:"Ambil 'inti' dari ide liar & pindahkan ke sesuatu yang nyata. Ini teknik 'batu loncatan'.",hint:"Ambil intinya & pindahkan, atau coret langsung?"},
{n:27,type:"tf",micro:"Semua ide harus realistis?",q:"Benar atau Salah: Selama sesi menghasilkan ide, semua ide yang disebut harus langsung realistis & bisa dikerjakan.",answer:false,explain:"Sebaliknya, memaksa 'harus realistis' sejak awal menyensor ide sebelum sempat berkembang. Uji kelayakan dilakukan pada tahap memilih, bukan tahap menghasilkan.",hint:"Harus realistis sejak awal, atau kelayakan diuji belakangan?"},
{n:28,type:"tf",micro:"Membangun ide bersama",q:"Benar atau Salah: Sebuah ide biasa sering menjadi ide hebat setelah beberapa orang menambahkan bagian mereka masing-masing.",answer:true,explain:"Ide jarang lahir sempurna. 'Efek bola salju' — tiap tambahan membuatnya lebih kuat — adalah kekuatan curah gagasan kelompok.",hint:"Ide bisa tumbuh dari tambahan orang lain, atau harus sempurna sejak awal?"},
{n:29,type:"mcq",micro:"Jumlah bukan segalanya",q:"Setelah menghasilkan 40 ide, kesalahan yang perlu dihindari:",options:["Menyaring lalu memilih beberapa ide untuk dikembangkan dengan kriteria jelas","Mengelompokkan ide-ide mirip supaya daftar panjang lebih mudah dilihat","Berhenti di situ & tidak pernah menyaring atau mengembangkan satu pun"],answer:2,explain:"Curah gagasan tanpa tindak lanjut hanya jadi daftar. Nilai muncul saat ide dipilih & dikerjakan.",hint:"Berhenti di daftar, atau lanjut menyaring & mengerjakan?"},
{n:30,type:"order",micro:"Dari 30 ide ke 1 rencana",q:"Urutkan langkah menindaklanjuti hasil curah gagasan.",items:["Kelompokkan ide-ide yang mirip menjadi beberapa tema","Untuk tiap tema, pilih 1-2 ide paling menjanjikan","Uji cepat: apakah masuk akal dengan waktu, biaya, & tenaga yang ada?","Pilih satu ide untuk dibuat purwarupa atau dicoba dulu"],answer:[0,1,2,3],explain:"Kelompokkan → pilih per tema → uji kelayakan → pilih satu untuk dicoba. Menyempit bertahap.",hint:"Mengelompokkan sebelum atau sesudah menguji kelayakan?"},
{n:31,type:"mcq",micro:"Pertanyaan pemantik",q:"Untuk menghidupkan sesi yang macet, pertanyaan pemantik yang berguna:",options:["'Bagaimana kalau kita punya anggaran tak terbatas? Bagaimana kalau harus gratis total? Apa yang akan dilakukan orang di 100 tahun lagi?'","'Kenapa kalian tidak punya ide? Masa tak ada satu pun yang terpikir sedari tadi?' sambil menunjuk satu per satu anggota, dengan nada kesal","'Ayo cepat, waktunya hampir habis, yang penting ada satu ide dulu supaya kita selesai, kalau tidak nanti nilai kita kurang'"],answer:0,explain:"Mengganti batasan (uang, waktu, zaman) memaksa otak keluar dari jalur yang sama & memunculkan ide baru.",hint:"Ubah batasan untuk memancing, atau desak & salahkan?"},
{n:32,type:"tf",micro:"Diam tanda tidak berkontribusi?",q:"Benar atau Salah: Anggota yang diam selama curah gagasan pasti tidak punya ide yang berguna.",answer:false,explain:"Sebaliknya, banyak orang berpikir lebih baik secara tertulis atau butuh waktu memproses. Memberi cara menyumbang selain bicara lantang sering memunculkan ide terbaik.",hint:"Diam = tidak berguna, atau butuh cara lain menyumbang?"},
{n:33,type:"mcq",micro:"Menghargai ide, bukan orangnya",q:"Setelah sesi, saat memilih ide, cara yang adil:",options:["Pilih ide ketua kelompok karena ia bertanggung jawab atas hasil","Nilai ide berdasarkan isinya, bukan siapa yang menyebutnya","Pilih ide anggota paling populer supaya semua senang"],answer:1,explain:"Ide bagus bisa datang dari siapa saja. Menilai berdasarkan orang membuat kelompok kehilangan ide terbaik.",hint:"Nilai isi ide, atau siapa yang mengucap?"},
{n:34,type:"mcq",micro:"Curah gagasan berulang",q:"Kalau sesi pertama belum menghasilkan ide yang memuaskan, sebaiknya...",options:["Paksakan memilih ide terbaik dari yang lemah itu supaya sesi tetap selesai tepat waktu","Batalkan proyeknya karena kelompok tampaknya belum punya ide yang cukup bagus","Istirahat sebentar lalu lakukan sesi kedua dengan sudut atau pertanyaan yang berbeda"],answer:2,explain:"Ide sering datang setelah 'inkubasi' (jeda). Sesi kedua dengan bingkai baru biasanya lebih kaya.",hint:"Jeda lalu sesi kedua, atau paksa pilih dari yang lemah?"},
{n:35,type:"mcq",micro:"Menuliskan pertanyaan dengan baik",q:"Manakah pertanyaan curah gagasan yang paling membuka?",options:["'Dengan cara apa saja kita bisa membuat perpustakaan lebih sering dikunjungi?'","'Apakah perpustakaan kita memang perlu diperbaiki atau sebaiknya dibiarkan seperti sekarang ini?'","'Siapa saja di kelas ini yang jarang sekali datang & meminjam buku di perpustakaan sekolah?'"],answer:0,explain:"'Dengan cara apa saja...' mengundang banyak jawaban. Pertanyaan ya/tidak & pertanyaan 'siapa' mempersempit.",hint:"Mengundang banyak jawaban, atau ya/tidak?"},
{n:36,type:"mcq",micro:"Kritik yang membangun (nanti)",q:"Saat akhirnya menilai ide, cara memberi kritik yang membangun:",options:["Diam saja & memilih ide secara diam-diam tanpa memberi tahu alasan atau tanggapan kepada pemiliknya","Sebut kelebihannya dulu, lalu 'yang perlu dipikirkan adalah...', lalu usul perbaikan","Cukup bilang 'ide ini jelek' supaya pemiliknya cepat mengerti & tidak mengulanginya lagi lain kali"],answer:1,explain:"Kritik yang jelas + usul perbaikan membantu ide berkembang. Sekadar 'jelek' tidak memberi jalan.",hint:"Sebut masalah + usul perbaikan, atau vonis 'jelek'?"},
{n:37,type:"tf",micro:"Menggabungkan dua ide",q:"Benar atau Salah: Dua ide yang masing-masing kurang kuat kadang bisa digabung menjadi satu ide yang jauh lebih baik.",answer:true,explain:"Menggabungkan (mis. 'lomba' + 'kebersihan kelas' → 'lomba kelas terbersih dengan poin mingguan') sering menghasilkan ide terkuat.",hint:"Bisa digabung jadi lebih baik, atau ide lemah selalu tetap lemah?"},
{n:38,type:"mcq",micro:"Batas curah gagasan",q:"Curah gagasan KURANG cocok dipakai untuk...",options:["Mencari banyak kemungkinan solusi untuk masalah terbuka yang belum punya satu jawaban tetap yang disepakati","Memancing ide proyek kelas yang bisa dikembangkan oleh seluruh murid secara bersama-sama","Keputusan yang butuh jawaban tunggal & pasti dengan cepat (mis. 'evakuasi lewat pintu mana saat kebakaran')"],answer:2,explain:"Untuk situasi darurat atau yang sudah ada prosedur bakunya, kita ikuti prosedur, bukan curah gagasan.",hint:"Situasi darurat berprosedur, atau masalah terbuka?"},
{n:39,type:"mcq",micro:"Menyimpan ide sisa",q:"Ide yang tidak dipilih sekarang sebaiknya...",options:["Disimpan dalam 'daftar ide' — mungkin cocok untuk masalah atau waktu yang lain","Dibuang seluruhnya karena tak sesuai dengan masalah yang sedang dibahas","Dilarang disebut lagi supaya sesi tetap fokus pada masalah hari ini"],answer:0,explain:"Ide yang belum pas hari ini bisa jadi solusi bulan depan. Bank ide adalah aset kelompok.",hint:"Simpan untuk nanti, atau buang seluruhnya?"},
{n:40,type:"open",micro:"Menganalisis sesi curah gagasan",q:"Bayangkan sesi curah gagasan kelasmu: 3 orang bicara terus, sisanya diam; setiap ide baru langsung dikomentari 'ah tidak mungkin'; sesi berhenti setelah 6 ide. Sebutkan 3 hal yang membuat sesi itu kurang efektif, dan untuk masing-masing tulis satu perbaikan konkret.",explain:"Jawaban baik: mengenali 3 masalah nyata (partisipasi tidak merata, kritik dini, berhenti terlalu cepat) & memberi perbaikan yang spesifik & bisa dilakukan untuk masing-masing, bukan sekadar 'harus lebih baik'.",hint:"Pikirkan: siapa yang bicara, kapan kritik boleh masuk, & berapa banyak ide sebelum berhenti.",sample:"Masalah 1: Hanya 3 orang bicara, sisanya diam, jadi banyak sudut pandang hilang. Perbaikan: mulai dengan 2 menit menulis ide sendiri di kertas, lalu ronde giliran sehingga setiap orang menyumbang minimal satu ide. Masalah 2: Setiap ide langsung dikritik 'tidak mungkin', jadi orang takut menyebut ide. Perbaikan: sepakati aturan di awal, tidak ada kritik selama fase menghasilkan; komentar & penilaian ditunda ke sesi kedua, dan pasang isyarat (mis. kata 'parkir dulu') kalau ada yang lupa. Masalah 3: Sesi berhenti di 6 ide, terlalu cepat, ide masih di permukaan. Perbaikan: tetapkan target minimal 20 ide dalam 8 menit & pakai pertanyaan pemantik ('bagaimana kalau gratis total? bagaimana kalau untuk 1000 orang?') saat aliran melambat."},
{n:41,type:"mcq",micro:"Mind map",q:"'Peta pikiran' (mind map) membantu curah gagasan dengan...",options:["Menghapus ide yang tak muat di kertas sehingga hanya tersisa ide yang paling pendek","Menaruh masalah di tengah lalu menarik cabang ke segala arah, tiap cabang memicu cabang baru","Menyusun semua ide dalam satu daftar lurus dari atas ke bawah tanpa hubungan antar-ide"],answer:1,explain:"Struktur bercabang meniru cara pikiran menghubungkan hal & membuat kita melihat kaitan yang tak terduga.",hint:"Bercabang ke segala arah, atau daftar lurus?"},
{n:42,type:"mcq",micro:"SCAMPER",q:"Teknik SCAMPER memancing ide dengan bertanya, untuk sebuah benda/proses: bisakah kita...",options:["Menyalin persis ide orang lain supaya hasilnya sudah terbukti berhasil sebelumnya di tempat lain","Berhenti memikirkannya begitu muncul satu jawaban yang terdengar cukup baik bagi kita semua","Ganti, Gabung, Sesuaikan, Modifikasi, Pakai untuk hal lain, Hilangkan sebagian, Balik/susun ulang"],answer:2,explain:"Tiap huruf SCAMPER adalah satu 'pengungkit'. Menerapkannya satu per satu pada objek menghasilkan banyak varian ide.",hint:"Serangkaian cara mengubah objek, atau menyalin persis?"},
{n:43,type:"mcq",micro:"Kata acak",q:"Teknik 'kata acak': ambil kata sembarang (mis. 'awan') untuk masalah 'membuat tempat sampah lebih menarik'. Cara pakainya:",options:["Cari sifat 'awan' (ringan, berubah bentuk, di atas) lalu hubungkan: tempat sampah ringan yang bentuknya berubah saat penuh","Abaikan kata itu karena tak berhubungan dengan masalah sampah dan hanya mengacaukan pikiran kelompok kita","Ganti masalahnya jadi soal awan supaya kata acak itu dapat dipakai langsung dalam sesi curah gagasan hari ini juga"],answer:0,explain:"Kata acak memaksa koneksi baru yang tidak akan muncul kalau kita hanya memikirkan masalahnya langsung.",hint:"Ambil sifat kata & hubungkan, atau abaikan?"},
{n:44,type:"mcq",micro:"Brainwriting 6-3-5",q:"Dalam 'brainwriting', tiap orang menulis beberapa ide di kertas lalu menggeser kertasnya ke tetangga. Manfaatnya:",options:["Menyembunyikan ide setiap orang dari kelompok supaya tak ada yang bisa mengambil atau menilainya","Setiap orang membangun di atas ide tertulis orang lain tanpa suara dominan menguasai","Membuat sesi sunyi dan tak produktif karena semua sibuk menulis tanpa saling bicara"],answer:1,explain:"Menggabungkan kekuatan menulis sendiri (keragaman) dengan membangun bersama (bola salju), tanpa perlu bicara lantang.",hint:"Membangun bersama tanpa dominasi, atau menyembunyikan ide?"},
{n:45,type:"tf",micro:"Batasan memicu ide",q:"Benar atau Salah: Menambahkan batasan seperti 'idenya harus bisa dibuat dari barang bekas saja' sering justru menghasilkan lebih banyak ide kreatif.",answer:true,explain:"Batasan mempersempit ruang sehingga otak berhenti memilih jawaban umum & mulai mencari jalan yang tidak biasa.",hint:"Batasan memicu kreativitas, atau selalu menghambat?"},
{n:46,type:"mcq",micro:"Bagaimana orang lain",q:"Pertanyaan 'Bagaimana [seorang koki / anak TK / insinyur / nenek] akan menyelesaikan masalah ini?' berguna karena...",options:["Kita jadi bisa menyalahkan orang-orang itu bila ternyata masalahnya tidak juga bisa terpecahkan","Tak ada manfaatnya, sebab koki atau anak TK tidak mengerti masalah kita sedikit pun dan hanya membingungkan","Meminjam sudut pandang berbeda memunculkan ide yang tidak terpikir dari sudut pandang kita sendiri"],answer:2,explain:"Tiap 'peran' punya kebiasaan berpikir berbeda. Membayangkannya adalah cara cepat menambah keragaman ide.",hint:"Meminjam sudut pandang lain, atau tak berguna?"},
{n:47,type:"mcq",micro:"Curah gagasan visual",q:"Menggambar ide (sketsa kasar), bukan hanya menuliskannya, membantu karena...",options:["Gambar memaksa kita memikirkan bentuk & cara kerja yang konkret, & sering memicu ide tambahan","Gambar lebih lambat daripada tulisan dan tak berguna untuk menghasilkan ide baru yang bagus","Hanya anak yang berbakat menggambar yang boleh ikut karena gambar harus bagus dulu di kelas"],answer:0,explain:"Sketsa 'buruk' pun mengungkap pertanyaan ('bagian ini menyambung ke mana?') yang memunculkan ide baru.",hint:"Membuat ide konkret & memicu tambahan, atau buang waktu?"},
{n:48,type:"mcq",micro:"Sendiri lalu kelompok",q:"Urutan yang sering paling produktif:",options:["Hanya sendiri-sendiri dari awal sampai akhir, tanpa berkumpul sebagai kelompok","Curah gagasan sendiri dulu (5 menit) → gabungkan di kelompok → kembangkan bersama","Langsung berkelompok sejak menit pertama tanpa memberi waktu berpikir sendiri dulu"],answer:1,explain:"Sesi sendiri menjaga keragaman & jumlah ide; sesi kelompok membangun & menggabungkan. Keduanya, berurutan.",hint:"Sendiri lalu kelompok, atau langsung kelompok saja?"},
{n:49,type:"mcq",micro:"Menempel ide di dinding",q:"Menuliskan tiap ide di kertas tempel terpisah & menempelnya di dinding memungkinkan kita...",options:["Kehilangan ide lebih cepat karena kertas kecil mudah jatuh dan tercecer","Membuat dinding kelas kotor dan penuh kertas tanpa alasan jelas","Memindah & mengelompokkan ide dengan mudah saat menyaring nanti"],answer:2,explain:"Ide yang bisa dipindah-pindah memudahkan tahap 'kelompokkan yang mirip' & melihat pola.",hint:"Memudahkan pengelompokan, atau menghilangkan ide?"},
{n:50,type:"order",micro:"Teknik kata acak",q:"Urutkan langkah memakai teknik kata acak.",items:["Tuliskan masalah yang ingin dipecahkan","Ambil satu kata benda secara acak (buka kamus/tunjuk benda)","Tuliskan 4-5 sifat atau ciri kata itu","Paksa hubungkan tiap sifat dengan masalah untuk memunculkan ide"],answer:[0,1,2,3],explain:"Masalah → kata acak → sifat-sifatnya → hubungkan paksa. Kekuatannya ada di langkah menghubungkan.",hint:"Menuliskan sifat kata sebelum atau sesudah menghubungkannya ke masalah?"},
{n:51,type:"mcq",micro:"Membingkai ulang masalah",q:"Sebelum curah gagasan, menuliskan masalah dalam 3 bentuk berbeda (mis. 'kurangi antrean' / 'buat menunggu terasa singkat' / 'hilangkan kebutuhan antre') berguna karena...",options:["Tiap bingkai membuka kumpulan ide yang berbeda","Membingungkan kelompok karena masalah dibahas berulang","Membuang waktu, sebab satu bingkai sudah cukup"],answer:0,explain:"Bingkai 'buat menunggu terasa singkat' memunculkan ide (musik, layar info) yang tidak muncul dari 'kurangi antrean'.",hint:"Tiap bingkai membuka ide berbeda, atau satu cukup?"},
{n:52,type:"tf",micro:"Ronde giliran",q:"Benar atau Salah: Memakai 'ronde giliran' di mana tiap orang menyebut ide bergantian tidak berpengaruh pada kelompok yang biasanya didominasi satu-dua orang.",answer:false,explain:"Sebaliknya, giliran yang jelas menjamin ruang bagi semua & sering memunculkan ide dari anggota yang biasanya diam.",hint:"Membantu pemerataan suara, atau tidak berpengaruh?"},
{n:53,type:"mcq",micro:"Kombinasi paksa",q:"Teknik 'kombinasi paksa': daftar fitur di kolom A (bahan, bentuk, cara pakai) & kolom B, lalu pasangkan acak. Tujuannya:",options:["Menghitung berapa banyak kombinasi yang mungkin dari kolom yang sudah ditulis","Menemukan gabungan yang tidak akan terpikir kalau memilih 'yang masuk akal' saja","Membuat daftar panjang tanpa guna untuk menyelesaikan masalah yang dihadapi"],answer:1,explain:"Memasangkan acak melewati penilaian otomatis kita & memunculkan gabungan mengejutkan yang layak dipertimbangkan.",hint:"Menemukan gabungan tak terduga, atau sekadar menghitung?"},
{n:54,type:"mcq",micro:"Menyaring dengan kriteria",q:"Setelah punya banyak ide, cara memilih yang lebih objektif:",options:["Pilih ide yang paling ramai didukung teriakan anggota yang suaranya paling keras di kelompok","Pilih ide yang terakhir disebutkan karena paling segar dalam ingatan anggota kelompok","Sepakati 2-3 kriteria (mis. mudah dicoba, murah, berdampak) lalu nilai tiap ide terhadapnya"],answer:2,explain:"Kriteria yang disepakati bersama membuat pemilihan adil & bisa dijelaskan, bukan sekadar selera.",hint:"Nilai terhadap kriteria, atau ikut yang paling ramai?"},
{n:55,type:"mcq",micro:"Waktu inkubasi",q:"'Inkubasi' dalam menghasilkan ide berarti...",options:["Meninggalkan masalah sejenak (tidur, jalan-jalan) & membiarkan pikiran bawah sadar bekerja","Memaksakan diri berpikir tanpa henti berjam-jam sampai ide bagus akhirnya muncul sendiri","Menyerah pada masalah itu dan tak mencoba memikirkannya lagi nanti di waktu lain mana pun"],answer:0,explain:"Banyak ide 'aha' muncul saat kita tidak sedang memikirkannya. Jeda yang disengaja adalah bagian dari proses.",hint:"Beri jeda pada pikiran, atau paksa tanpa henti?"},
{n:56,type:"tf",micro:"Menulis ide buruk sengaja",q:"Benar atau Salah: Sengaja membuat daftar 'ide terburuk yang mungkin' lalu membalik tiap poin bisa menghasilkan solusi yang baik.",answer:true,explain:"Teknik 'ide terburuk' melepaskan tekanan harus benar & sering membuka jalan: kebalikan dari ide buruk sering ide bagus.",hint:"Membalik ide terburuk bisa berguna, atau buang waktu?"},
{n:57,type:"mcq",micro:"Membatasi jumlah kata",q:"Meminta tiap ide ditulis maksimal 5 kata saat curah gagasan cepat berguna karena...",options:["Membatasi peserta agar hanya anak yang menulis cepat ikut","Memaksa ide keluar cepat & banyak, detail dikembangkan nanti","Membuat ide yang muncul tak bisa dipahami, termasuk oleh penulisnya"],answer:1,explain:"Ringkas = cepat = banyak. Ide singkat bisa diperjelas di tahap pengembangan.",hint:"Cepat & banyak, atau bikin tak terpahami?"},
{n:58,type:"mcq",micro:"Curah gagasan digital",q:"Saat kelompok berjauhan, alat yang membantu curah gagasan bersama:",options:["Hanya panggilan suara tanpa mencatat, supaya anggota fokus mendengarkan","Tak mungkin dilakukan dari jarak jauh, jadi ditunda sampai bisa berkumpul","Papan tulis daring bersama tempat semua menempel catatan sekaligus"],answer:2,explain:"Papan daring meniru 'dinding kertas tempel' & memungkinkan semua menyumbang bersamaan, bahkan yang malu bicara.",hint:"Papan daring bersama, atau mustahil dari jarak jauh?"},
{n:59,type:"mcq",micro:"Menetapkan pertanyaan yang tepat",q:"Tanda pertanyaan curah gagasan terlalu sempit:",options:["Hanya menghasilkan 2-3 ide sebelum semua orang buntu","Menghasilkan 30 ide beragam dengan sangat mudah","Membuat anggota tertawa karena pertanyaannya terdengar lucu"],answer:0,explain:"Kalau ide cepat kering, perlebar pertanyaannya ('bagaimana membuat kelas nyaman' bukan 'warna cat apa untuk kelas').",hint:"Cepat buntu = terlalu sempit, atau terlalu luas?"},
{n:60,type:"open",micro:"Pakai satu teknik",q:"Pilih satu masalah nyata (mis. 'buku perpustakaan sering rusak' atau 'sulit menemukan teman untuk belajar bersama'). Pilih SATU teknik (SCAMPER, kata acak, brainwriting, 'bagaimana orang lain', atau ide terburuk). Terapkan teknik itu langkah demi langkah & hasilkan minimal 8 ide. Tulis prosesnya.",explain:"Jawaban baik: teknik diterapkan secara nyata langkah demi langkah (terlihat jejak tekniknya), menghasilkan minimal 8 ide yang benar-benar berbeda, & ada sedikit refleksi tentang ide mana yang menjanjikan. Yang dinilai proses & keberagaman, bukan kesempurnaan ide.",hint:"Tunjukkan tiap langkah teknik menghasilkan ide apa, jangan hanya menempel daftar ide di akhir.",sample:"Masalah: buku perpustakaan sering rusak. Teknik: SCAMPER. Ganti: ganti sampul kertas dengan sampul plastik tebal yang bisa dilap. Gabung: gabungkan kartu peminjaman dengan 'kartu kondisi buku' sehingga kerusakan tercatat siapa & kapan. Sesuaikan: sesuaikan aturan, buku tebal/mahal hanya boleh dibaca di tempat. Modifikasi: perbesar tulisan 'jaga aku' & gambar di halaman pertama tiap buku. Pakai untuk hal lain: buku yang sudah rusak parah dijadikan bahan kolase seni kelas, bukan dibuang. Hilangkan: hilangkan kebiasaan menumpuk buku di lantai dengan menambah rak pengembalian sementara. Balik/susun ulang: alih-alih menghukum yang merusak, beri penghargaan bulanan untuk kelas dengan buku paling terawat. Ide tambahan dari proses: sesi 'reparasi buku' rutin bersama siswa. Total 8 ide. Yang paling menjanjikan menurutku: kartu kondisi buku + penghargaan kelas terawat, karena mengubah kebiasaan, bukan hanya menambal."},
{n:61,type:"mcq",micro:"Penambatan pada ide pertama",q:"'Penambatan' (anchoring) dalam curah gagasan kelompok:",options:["Ketika kelompok punya terlalu banyak ide sehingga tak satu pun terpilih","Ide pertama yang disebut diam-diam membatasi arah semua ide berikutnya","Menambatkan kertas catatan ke papan supaya tak terbang tertiup angin"],answer:1,explain:"Melawannya: minta beberapa ide tertulis dulu sebelum ada yang bicara, atau sengaja mulai dari sudut yang berbeda-beda.",hint:"Ide pertama membatasi arah, atau soal kertas terbang?"},
{n:62,type:"mcq",micro:"Evaluasi menyusup",q:"Tanda kelompok diam-diam sudah menilai padahal masih fase menghasilkan:",options:["Semua ide ditulis pencatat tanpa komentar dari anggota mengenai isinya, dan suasana tenang","Jumlah ide terus bertambah cepat dan semua ikut menyumbang dengan bebas dan santai","Ada yang berkata 'itu terlalu mahal' atau 'nanti tidak diizinkan' saat ide baru muncul"],answer:2,explain:"Kalimat 'terlalu ...' adalah penilaian. Fasilitator perlu mengingatkan: 'parkir dulu, kita nilai nanti'.",hint:"Muncul kata 'terlalu ...', atau ide mengalir tanpa komentar?"},
{n:63,type:"mcq",micro:"Terlalu cepat jatuh cinta pada satu ide",q:"Bahaya 'jatuh cinta' pada satu ide di awal:",options:["Kita berhenti mencari & tidak sadar ada ide lain yang lebih baik atau lebih mudah","Tak ada bahayanya, karena jatuh cinta pada ide itu tanda idenya memang bagus sekali","Membuat kelompok punya terlalu banyak pilihan sehingga sulit menentukan salah satunya"],answer:0,explain:"Aturan sehat: selalu hasilkan minimal 3 opsi yang layak sebelum memilih, meski opsi pertama terasa menarik.",hint:"Berhenti mencari terlalu dini, atau tanda pasti ide bagus?"},
{n:64,type:"tf",micro:"Lebih banyak orang selalu lebih baik?",q:"Benar atau Salah: Menambah jumlah orang dalam sesi curah gagasan kelompok selalu meningkatkan jumlah & kualitas ide.",answer:false,explain:"Sebaliknya, kelompok yang terlalu besar sering menghasilkan lebih sedikit ide per orang (sebagian menganggur, sebagian dominan). Kelompok kecil atau sesi menulis sendiri sering lebih produktif.",hint:"Makin banyak orang makin baik, atau ada titik jenuh?"},
{n:65,type:"mcq",micro:"Kapan berhenti menghasilkan",q:"Waktu yang wajar berhenti fase menghasilkan ide:",options:["Jangan berhenti, sebab mungkin saja ada ide yang lebih baik di menit berikutnya, jadi lanjutkan terus","Saat ide baru mulai jarang & sebagian besar hanya pengulangan, DAN sudah ada cukup ragam untuk dipilih","Segera setelah muncul ide pertama yang lumayan bagus, supaya kelompok bisa langsung mulai mengerjakannya"],answer:1,explain:"Berhenti terlalu dini = ide dangkal. Terlalu lama = lelah & mengulang. Tanda pas: aliran melambat + ragam cukup.",hint:"Aliran melambat & ragam cukup, atau ide lumayan pertama?"},
{n:66,type:"mcq",micro:"Ide banyak tapi mirip semua",q:"Kamu punya 25 ide tapi semuanya versi kecil dari satu gagasan. Yang perlu dilakukan:",options:["Anggap saja sudah cukup banyak & pilih salah satu dari 25 ide itu karena jumlahnya sudah banyak","Gabungkan semua ide itu menjadi satu ide besar yang isinya mencakup seluruh versi kecil tadi sekaligus","Sesi tambahan dengan teknik yang memaksa sudut baru (kata acak, peran orang lain, ubah batasan)"],answer:2,explain:"Banyak ≠ beragam. Kalau semua serumpun, gunakan teknik yang sengaja menjauhkan dari jalur itu.",hint:"Paksa sudut baru, atau anggap cukup?"},
{n:67,type:"mcq",micro:"Menilai dengan jujur",q:"Saat menilai ide sendiri vs ide teman, jebakan yang perlu disadari:",options:["Kita cenderung lebih longgar menilai ide sendiri & lebih keras pada ide orang lain","Kita menilai dengan adil secara alami sehingga tak perlu kriteria yang disepakati","Kita lebih keras pada ide sendiri dan lebih longgar pada ide orang lain di kelompok"],answer:0,explain:"Menyadari bias ini membantu: nilai semua ide dengan kriteria yang sama, tutupi nama pengusulnya kalau perlu.",hint:"Lebih longgar pada ide sendiri, atau selalu adil?"},
{n:68,type:"mcq",micro:"Ide bagus, waktu salah",q:"Sebuah ide bagus tapi butuh sumber daya yang belum ada sekarang. Sikap yang tepat:",options:["Paksakan dikerjakan sekarang meski sumber dayanya belum ada, supaya tak sia-sia","Catat di 'bank ide' dengan alasannya, tinjau lagi saat keadaan berubah","Buang saja karena tak bisa dikerjakan sekarang dan tak berguna disimpan"],answer:1,explain:"Ide bukan hanya untuk hari ini. Menyimpannya dengan konteks membuatnya siap dipakai saat waktunya tiba.",hint:"Simpan dengan konteks, atau buang / paksakan?"},
{n:69,type:"mcq",micro:"Fasilitator yang baik",q:"Tugas utama pemandu (fasilitator) sesi curah gagasan:",options:["Menyumbang ide paling banyak dibanding anggota lain agar sesi terlihat produktif di mata kelompok dan guru yang mengamati","Memutuskan sendirian ide mana yang menang di akhir sesi tanpa perlu bertanya kepada anggota lain","Menjaga aturan (tunda kritik, semua kebagian), mencatat, & memancing saat macet — bukan memaksakan idenya sendiri"],answer:2,explain:"Fasilitator melayani proses. Kalau ia mendominasi ide, sesi kehilangan keragaman.",hint:"Menjaga proses, atau mendominasi ide?"},
{n:70,type:"tf",micro:"Menghasilkan & memilih beda keterampilan",q:"Benar atau Salah: Menghasilkan banyak ide & memilih ide terbaik adalah keterampilan yang sama & paling baik dilakukan bersamaan.",answer:false,explain:"Sebaliknya, keduanya keterampilan berbeda: pikiran 'melebar' (banyak kemungkinan) & pikiran 'menyempit' (memilih) saling mengganggu bila dilakukan bersamaan, jadi pisahkan waktunya.",hint:"Dua mode terpisah, atau satu proses yang sama?"},
{n:71,type:"mcq",micro:"Dari daftar ke tindakan",q:"Hasil akhir sesi curah gagasan yang berguna adalah...",options:["Beberapa ide terpilih dengan langkah pertama yang jelas & siapa yang mengerjakan","Daftar panjang berisi 40 ide yang disimpan rapi di buku dan tak disentuh lagi","Perdebatan panjang tentang siapa yang idenya paling baik dan paling pantas menang"],answer:0,explain:"Ide tanpa langkah & penanggung jawab jarang terjadi. 'Ide terpilih + langkah + orang' adalah bentuk yang hidup.",hint:"Ide terpilih + langkah + orang, atau daftar yang diarsipkan?"},
{n:72,type:"mcq",micro:"Menghormati ide yang tidak dipilih",q:"Saat idemu tidak terpilih setelah proses yang adil, sikap dewasa:",options:["Terus mengungkit bahwa idemu lebih bagus supaya kelompok mempertimbangkannya lagi","Menerima, ikut mendukung ide terpilih, & menyimpan idemu untuk kesempatan lain","Ngambek dan menolak membantu mengerjakan ide terpilih karena prosesnya tak menghargaimu"],answer:1,explain:"Dalam kerja bersama, yang penting hasil kelompok. Ide yang kalah hari ini bisa menang besok.",hint:"Dukung hasil bersama, atau ngambek?"},
{n:73,type:"mcq",micro:"Curah gagasan vs riset",q:"Setelah punya ide terpilih, sebelum langsung membuat, langkah bijak:",options:["Langsung membuatnya sekarang juga tanpa mengecek, supaya tak ada waktu terbuang percuma bagi kelompok","Batalkan idenya kalau ternyata pernah dicoba orang lain, karena itu berarti tidak orisinal lagi","Cek cepat apakah sudah ada yang mencobanya & apa hasilnya — supaya belajar dari pengalaman orang"],answer:2,explain:"Ide 'sudah pernah dicoba' bukan berarti buruk, justru ada pelajaran gratis. Cek dulu, lalu perbaiki.",hint:"Belajar dari yang sudah mencoba, atau abaikan / batalkan?"},
{n:74,type:"mcq",micro:"Bias 'ide rumit terdengar pintar'",q:"Jebakan saat memilih ide:",options:["Memilih ide yang terdengar canggih & rumit padahal ide sederhana lebih mungkin berhasil","Memilih ide yang paling sederhana saja tanpa berpikir atau membandingkan dengan ide lain","Memilih berdasarkan satu kebiasaan lama kelompok tanpa membandingkan ide secara adil"],answer:0,explain:"Ide sederhana yang benar-benar dikerjakan mengalahkan ide megah yang tidak pernah selesai.",hint:"Tergoda yang rumit & canggih, atau menilai dengan kriteria?"},
{n:75,type:"order",micro:"Menyaring ide secara adil",q:"Urutkan langkah menyaring 30 ide menjadi 1 pilihan.",items:["Sepakati kriteria pemilihan (mis. dampak, kemudahan, biaya)","Kelompokkan ide yang mirip & buang duplikat","Beri tiap ide skor cepat terhadap kriteria","Pilih 2-3 skor tertinggi, diskusikan, lalu putuskan satu"],answer:[0,1,2,3],explain:"Kriteria dulu → rapikan daftar → skor → diskusi & putuskan. Kriteria di awal menjaga proses tetap adil.",hint:"Menyepakati kriteria di awal atau di akhir?"},
{n:76,type:"tf",micro:"Ide dari luar bidang",q:"Benar atau Salah: Mengundang seseorang yang bukan 'ahli' masalah ini ke sesi curah gagasan bisa merugikan karena idenya pasti tidak relevan.",answer:false,explain:"Sebaliknya, orang luar sering menyumbang ide segar justru karena tidak terikat 'cara yang biasa dilakukan'. Keragaman latar belakang memperkaya ide.",hint:"Orang luar merugikan, atau bisa menyegarkan?"},
{n:77,type:"mcq",micro:"Menghindari sesi yang sia-sia",q:"Curah gagasan cenderung sia-sia bila...",options:["Anggota ikut menyumbang ide dengan bebas dan suasana hangat serta penuh semangat","Tidak ada pertanyaan yang jelas, atau hasilnya tidak pernah ditindaklanjuti","Menghasilkan banyak ide beragam dan tindak lanjutnya dibahas jelas oleh anggota"],answer:1,explain:"Dua penyebab utama sesi gagal: masalah tidak jelas di depan, & tidak ada langkah setelahnya.",hint:"Masalah kabur & tanpa tindak lanjut, atau banyak ide & partisipasi?"},
{n:78,type:"mcq",micro:"Menggabungkan mode",q:"Cara sehat memakai kritik dalam proses kreatif secara keseluruhan:",options:["Kritik terus-menerus di setiap sesi, bahkan ketika kelompok sedang berusaha menghasilkan ide baru","Hindari kritik, sehingga ide dianggap bagus semuanya dan tak satu pun diperbaiki lagi oleh kelompok","Bergantian: sesi menghasilkan (tanpa kritik) lalu sesi menilai (kritik membangun), berulang bila perlu"],answer:2,explain:"Kritik penting, tempatnya di sesi terpisah. Bergantian antara 'melebar' & 'menyempit' adalah irama kerja kreatif.",hint:"Bergantian mode, atau kritik terus / tidak sama sekali?"},
{n:79,type:"mcq",micro:"Mengukur keberhasilan sesi",q:"Sesi curah gagasan bisa disebut berhasil bila...",options:["Menghasilkan beberapa ide beragam yang layak, & kelompok tahu langkah selanjutnya","Anggota langsung setuju pada satu ide sejak menit pertama sehingga sesi cepat selesai","Menghasilkan satu ide saja dan tak ada perdebatan di antara anggota kelompok"],answer:0,explain:"Keberagaman + kejelasan langkah selanjutnya = sesi yang berguna. Kesepakatan instan sering tanda kurang menggali.",hint:"Ragam ide + langkah jelas, atau setuju instan?"},
{n:80,type:"open",micro:"Merancang sesi",q:"Kelasmu perlu ide untuk acara perpisahan dengan dana terbatas. Rancang sesi curah gagasan 20 menit: tulis (a) pertanyaan pemantik yang tepat, (b) aturan yang kamu umumkan di awal, (c) 1 teknik yang akan dipakai & alasannya, (d) cara memastikan semua ikut, (e) apa yang terjadi di 5 menit terakhir.",explain:"Jawaban baik: pertanyaan pemantik yang terbuka & menyertakan batasan dana, aturan yang menunda kritik & mengejar jumlah, teknik yang cocok dengan kondisi kelas + alasan, cara konkret pemerataan partisipasi, & penutup yang mengubah ide jadi langkah (kriteria + pilih + penanggung jawab).",hint:"Pastikan tiap bagian menjawab pertanyaannya secara spesifik; bagian (e) harus menghasilkan tindakan, bukan sekadar 'memilih'.",sample:"(a) Pertanyaan pemantik: 'Dengan cara apa saja kita bisa membuat acara perpisahan yang berkesan dengan dana di bawah Rp X?' (b) Aturan: tidak ada kritik selama 12 menit pertama; kejar minimal 30 ide; ide liar & lucu diterima & dicatat; bangun ide teman dengan 'ya, dan'. (c) Teknik: brainwriting, tiap orang menulis 3 ide di kertas selama 3 menit lalu menggeser ke teman untuk ditambah, karena kelas besar & beberapa siswa malu bicara di depan. (d) Memastikan semua ikut: setelah brainwriting, ronde giliran cepat, tiap kelompok kecil membacakan 2 ide favoritnya; pencatat menuliskan semua di papan tanpa menyaring. (e) 5 menit terakhir: kelompokkan ide sejenis, sepakati 3 kriteria (murah, melibatkan banyak orang, bisa disiapkan dalam 2 minggu), pilih 3 ide teratas & tentukan siapa yang mencari tahu detailnya sebelum pertemuan berikutnya."},
{n:81,type:"mcq",micro:"Skenario: sesi macet total",q:"10 menit berjalan, kelompok baru punya 4 ide & semua terdiam. Langkah terbaik:",options:["Paksa kelompok dengan pertanyaan yang sama persis sampai ada yang berhasil menjawab, walau anggota sudah kehabisan akal","Ganti pertanyaan atau tambah batasan ekstrem ('bagaimana kalau harus selesai hari ini juga?') untuk memancing arah baru","Bubarkan sesi sekarang dan simpulkan bahwa kelompok ini tak bisa menghasilkan ide lain pada masalah itu, lalu ganti topik"],answer:1,explain:"Kemacetan biasanya soal bingkai, bukan soal orang. Ubah bingkai → aliran ide kembali.",hint:"Ubah bingkai/batasan, atau bubar / paksa sama?"},
{n:82,type:"mcq",micro:"Skenario: satu ide didukung ramai-ramai",q:"Dalam 3 menit pertama, satu ide langsung disukai semua & orang berhenti mengusulkan. Yang sebaiknya dilakukan:",options:["Langsung tetapkan ide itu sebagai pemenang karena anggota sudah menyukainya sejak awal sesi tadi","Larang anggota menyebut ide itu lagi supaya kelompok terpaksa mencari ide lainnya yang baru","Akui ide itu menarik, lalu minta setiap orang tetap menyumbang minimal 2 ide lain sebelum menilai"],answer:2,explain:"Antusiasme dini adalah tanda 'penambatan'. Tetap butuh beberapa opsi layak sebelum memilih dengan yakin.",hint:"Tetap kumpulkan opsi lain, atau langsung tetapkan pemenang?"},
{n:83,type:"mcq",micro:"Skenario: ide dari anggota pendiam",q:"Anggota yang biasanya diam menulis ide bagus di kertas brainwriting. Cara merespons:",options:["Sebut idenya, akui kontribusinya di depan kelompok, & kembangkan bersama","Anggap itu kebetulan dan lewati supaya sesi berjalan lancar tanpa gangguan","Klaim sebagai ide bersama tanpa menyebut penulisnya agar terlihat kompak"],answer:0,explain:"Mengakui kontribusi anggota pendiam membuat mereka lebih berani menyumbang lain kali. Keragaman suara adalah aset.",hint:"Akui & kembangkan, atau lewati / klaim?"},
{n:84,type:"mcq",micro:"Skenario: batas waktu proyek dekat",q:"Tenggat 3 hari lagi & kelompok masih ragu antara 4 ide. Pendekatan yang tepat:",options:["Kerjakan keempat ide itu sekaligus dengan membagi anggota kelompok ke dalam empat bagian yang sama","Nilai cepat dengan kriteria 'mana yang paling mungkin selesai baik dalam 3 hari', pilih, & mulai","Terus curah gagasan untuk mencari ide kelima yang sempurna sampai tenggat waktunya benar-benar tiba"],answer:1,explain:"Saat waktu sempit, 'bisa selesai dengan baik' jadi kriteria utama. Ide selesai mengalahkan ide sempurna yang tidak jadi.",hint:"Pilih yang bisa selesai baik, atau kejar ide sempurna?"},
{n:85,type:"tf",micro:"Curah gagasan butuh latihan",q:"Benar atau Salah: Kemampuan menghasilkan banyak ide dengan cepat meningkat kalau sering dilatih, seperti keterampilan lain.",answer:true,explain:"Latihan rutin (mis. '10 ide sehari' untuk masalah kecil apa pun) membuat pikiran makin lancar menghasilkan gagasan.",hint:"Meningkat dengan latihan, atau bakat tetap?"},
{n:86,type:"mcq",micro:"Skenario: ide melanggar aturan",q:"Ide terbaik kelompok ternyata melanggar aturan sekolah. Sikap yang tepat:",options:["Tetap jalankan ide itu diam-diam supaya tak ketahuan dan tidak dilarang oleh pihak sekolah","Buang idenya tanpa mencari alternatif karena melanggar aturan itu sudah final dan tak bisa diubah","Ambil inti ide itu & cari versi yang tetap mematuhi aturan, atau tanyakan izin dengan usulan yang jelas"],answer:2,explain:"Batasan aturan adalah bagian dari masalah yang harus dipecahkan, bukan alasan menyerah atau melanggar.",hint:"Cari versi yang patuh / minta izin, atau langgar / buang?"},
{n:87,type:"mcq",micro:"Skenario: terlalu banyak ide bagus",q:"Kelompok punya 6 ide yang semuanya bagus & tidak bisa memilih. Cara maju:",options:["Uji tiap ide dengan pertanyaan 'mana yang bisa kita coba kecil-kecilan minggu ini?' lalu mulai dari situ","Pilih dengan undian tanpa banyak berpikir supaya cepat selesai dan tak ada perdebatan lagi di kelompok","Simpan semuanya dulu dan tak berbuat apa-apa sampai ada satu ide yang jelas unggul dari semuanya"],answer:0,explain:"Kalau sulit memilih di atas kertas, uji nyata berskala kecil memberi informasi yang tidak bisa didapat dari diskusi.",hint:"Uji kecil untuk memilih, atau undi / diam?"},
{n:88,type:"mcq",micro:"Skenario: kritik dari luar",q:"Setelah memilih ide, guru menunjukkan satu kelemahan besar. Respons kreatif:",options:["Langsung membuang ide itu & mulai lagi dari nol, karena kelemahan besar berarti ide itu gagal total","'Terima kasih, itu penting. Bagaimana kalau kita ubah bagian ini untuk mengatasinya?' lalu curah gagasan solusi kecil","Membela idenya mati-matian tanpa mendengarkan penjelasan guru, sebab kelompok sudah memilihnya dengan adil"],answer:1,explain:"Kelemahan yang ditunjukkan adalah bahan untuk perbaikan, bukan vonis. Curah gagasan lagi, kali ini untuk menambal.",hint:"Curah gagasan solusi kecil, atau membela / buang total?"},
{n:89,type:"mcq",micro:"Skenario: ide berulang tiap tahun",q:"Setiap tahun kelas mengusulkan ide acara yang sama. Cara memecah kebiasaan:",options:["Terima saja karena 'sudah tradisi' dan acara tahunan tak perlu diubah oleh panitia mana pun","Batalkan acaranya karena ide baru sulit dicari dan merepotkan panitia sekolah tahun ini","Mulai sesi dengan aturan 'ide yang sudah pernah dilakukan tidak dihitung' & pakai teknik kata acak"],answer:2,explain:"Melarang ide lama untuk sementara memaksa kelompok menggali wilayah baru. Batasan ini produktif.",hint:"Larang ide lama sementara, atau terima 'tradisi'?"},
{n:90,type:"order",micro:"Proyek mini curah gagasan",q:"Urutkan langkah proyek 'pecahkan satu masalah kelas dalam seminggu'.",items:["Hari 1: rumuskan masalah jadi pertanyaan 'bagaimana caranya kita' & curah gagasan 30 ide","Hari 2: kelompokkan ide, sepakati kriteria, pilih 2-3","Hari 3-5: uji kecil ide terpilih & catat hasilnya","Hari 6-7: pilih ide terbaik berdasarkan hasil uji & susun rencana penerapan"],answer:[0,1,2,3],explain:"Rumuskan & hasilkan → saring → uji kecil → putuskan dengan bukti. Keputusan akhir berdasarkan hasil uji, bukan hanya diskusi.",hint:"Menguji ide sebelum atau sesudah menyusun rencana akhir?"},
{n:91,type:"mcq",micro:"Skenario: menilai idemu sendiri menang",q:"Dalam pemungutan suara, idemu menang tipis. Salah satu teman merasa prosesnya kurang adil. Sikap yang baik:",options:["Dengarkan keberatannya, cek bersama apakah kriteria diterapkan adil, & bersedia mengulang pemilihan bila memang timpang","Abaikan saja keberatannya karena kamu sudah menang dan hasil pemungutan suara tidak bisa diubah lagi","Marah kepada temanmu karena dituduh curang padahal kamu merasa sudah bersikap jujur selama proses itu"],answer:0,explain:"Proses yang dirasakan adil oleh semua lebih berharga daripada 'menang' yang meninggalkan orang kecewa. Ini menjaga kerja sama ke depan.",hint:"Periksa keadilan proses, atau abaikan karena sudah menang?"},
{n:92,type:"tf",micro:"Ide vs pelaksanaan",q:"Benar atau Salah: Ide yang hebat tetapi tidak pernah dikembangkan atau dicoba nilainya kecil dibanding ide biasa yang benar-benar dikerjakan sampai selesai.",answer:true,explain:"Curah gagasan hanya berguna kalau menuntun ke tindakan. Ide di kepala tidak mengubah apa pun sampai dijalankan.",hint:"Ide hebat tak dikerjakan vs ide biasa yang selesai?"},
{n:93,type:"mcq",micro:"Skenario: menggabungkan ide pesaing",q:"Dua ide populer bersaing & kelompok terbelah. Langkah kreatif sebelum voting:",options:["Buang keduanya lalu cari ide ketiga yang benar-benar baru dari awal","Coba: 'Adakah cara menggabungkan bagian terbaik keduanya jadi satu ide?'","Langsung voting dan menangkan salah satu tanpa membahas kelebihan keduanya"],answer:1,explain:"Sering ide ketiga (gabungan) lebih kuat & menyatukan kelompok. Coba gabungkan dulu sebelum memilih menang-kalah.",hint:"Coba gabungkan yang terbaik dari keduanya, atau langsung voting?"},
{n:94,type:"mcq",micro:"Skenario: sesi online sepi",q:"Di papan daring, hanya 3 dari 10 orang menempel ide. Cara menghidupkan:",options:["Biarkan yang aktif saja yang mengisi papan, sebab yang lain mungkin tak punya ide dan tak perlu dipaksa","Tutup papan daring itu & ganti dengan panggilan suara di mana hanya satu orang yang berbicara","Beri waktu hening 3 menit di mana semua wajib menempel minimal 2 catatan, tanpa melihat punya orang lain dulu"],answer:2,explain:"Waktu hening + target minimal + tidak melihat punya orang lain dulu = semua menyumbang & idenya beragam.",hint:"Waktu hening + target wajib, atau biarkan yang aktif saja?"},
{n:95,type:"tf",micro:"Curah gagasan menyelesaikan segalanya?",q:"Benar atau Salah: Curah gagasan adalah alat untuk memunculkan banyak kemungkinan, bukan alat untuk memastikan sebuah ide pasti berhasil.",answer:true,explain:"Setelah curah gagasan tetap perlu memilih, menguji, & memperbaiki. Ia langkah awal proses kreatif, bukan seluruhnya.",hint:"Alat memunculkan kemungkinan, atau jaminan keberhasilan?"},
{n:96,type:"mcq",micro:"Skenario: ide bagus tapi tidak ada yang mau mengerjakan",q:"Ide terpilih bagus, tapi tidak ada yang mengajukan diri mengerjakan bagian tersulitnya. Yang perlu dibahas:",options:["Apakah idenya perlu disederhanakan, atau bagian sulit itu dipecah & dibagi rata dengan dukungan","Paksa satu orang saja untuk mengerjakannya sendirian sampai selesai tanpa bantuan dari anggota lain","Ganti ke ide lain yang lebih mudah dikerjakan tanpa diskusi dahulu dengan seluruh anggota kelompok"],answer:0,explain:"Ide yang tidak ada yang mau kerjakan adalah sinyal: mungkin terlalu berat, atau pembagian & dukungannya belum jelas.",hint:"Sederhanakan / bagi rata dengan dukungan, atau paksa satu orang?"},
{n:97,type:"mcq",micro:"Menilai keberagaman ide",q:"Cara cepat mengecek apakah kumpulan idemu cukup beragam:",options:["Lihat siapa yang menyumbang ide terbanyak, karena itu menunjukkan idenya sudah beragam","Lihat apakah ide-ide menyentuh sudut berbeda: teknologi, kebiasaan, aturan, orang, ruang, biaya","Hitung jumlah idenya; kalau sudah banyak, ide sudah beragam dari berbagai sudut pandang"],answer:1,explain:"Beragam berarti menyerang masalah dari banyak arah, bukan sekadar banyak versi dari satu arah.",hint:"Cek ragam sudut, atau cukup hitung jumlah?"},
{n:98,type:"mcq",micro:"Kebiasaan pribadi",q:"Kebiasaan yang menumbuhkan kemampuan menghasilkan ide dalam jangka panjang:",options:["Menunggu inspirasi datang sendiri kapan saja tanpa melatih atau mencatat apa-apa","Menghindari masalah kecil supaya otak tak perlu berpikir keras dan tak lekas lelah","Rutin melatih 'daftar 10 ide' untuk masalah kecil sehari-hari & mencatat pengamatan menarik"],answer:2,explain:"Seperti otot, kelancaran ide tumbuh dari latihan kecil & rutin, bukan menunggu momen ajaib.",hint:"Latihan kecil rutin, atau menunggu inspirasi?"},
{n:99,type:"mcq",micro:"Nilai sesungguhnya curah gagasan",q:"Selain menghasilkan ide, manfaat penting sesi curah gagasan kelompok:",options:["Semua anggota merasa ikut memiliki hasil karena idenya didengar, sehingga lebih semangat mengerjakan","Menentukan siapa di antara anggota yang paling pintar sehingga bisa dijadikan pemimpin tetap kelompok","Menghabiskan waktu pelajaran supaya tugas-tugas lain terasa lebih ringan dan tidak perlu dikerjakan hari itu"],answer:0,explain:"Rasa 'ini juga ideku' membuat pelaksanaan lebih lancar. Proses yang inklusif membangun komitmen.",hint:"Membangun rasa ikut memiliki, atau menilai siapa terpintar?"},
{n:100,type:"open",micro:"Kapstone: rancang & jalankan",q:"Pilih satu masalah nyata di lingkunganmu. Buat rencana lengkap: (a) pertanyaan 'bagaimana caranya kita', (b) rencana sesi menghasilkan ide (teknik, waktu, cara semua ikut), (c) kriteria memilih & cara menyaring, (d) rencana menguji ide terpilih dalam skala kecil, (e) bagaimana kamu akan tahu apakah ide itu berhasil.",explain:"Jawaban baik: masalah nyata & spesifik, sesi menghasilkan ide yang dirancang dengan teknik + pemerataan + target, kriteria pemilihan yang jelas & cara menyaring yang konkret, rencana uji skala kecil yang benar-benar kecil & terbatas waktu, & ukuran keberhasilan yang bisa diperiksa dengan angka atau bukti, bukan perasaan.",hint:"Bagian tersulit biasanya (d) & (e), buat ujinya benar-benar kecil (satu petak, dua minggu) & ukuran keberhasilannya sesuatu yang bisa dihitung.",sample:"(a) Masalah: warga sekitar sering membuang sampah di lahan kosong dekat sekolah. Pertanyaan: 'Bagaimana caranya kita membuat orang berhenti membuang sampah di lahan kosong itu & menggunakannya untuk sesuatu yang berguna?' (b) Sesi: dua putaran. Putaran 1 brainwriting 5 menit (tiap orang 4 ide di kertas, digeser), putaran 2 mind map bersama di papan mengembangkan tema yang muncul. Waktu total 25 menit. Semua ikut lewat kertas + ronde giliran membacakan. Target 40 ide. (c) Kriteria: bisa dilakukan siswa & warga tanpa dana besar, berdampak dalam 1 bulan, tidak menimbulkan masalah baru. Menyaring: kelompokkan ide, buang duplikat, beri skor 1-3 per kriteria, ambil 3 teratas untuk didiskusikan. (d) Uji kecil: untuk ide terpilih (misal 'ubah lahan jadi kebun mini + papan nama pengelola'), coba di petak 3x3 meter selama 2 minggu, pasang papan, ajak 5 keluarga ikut merawat. (e) Ukuran keberhasilan: bandingkan jumlah kantong sampah liar di lahan itu sebelum & sesudah 2 minggu; hitung berapa keluarga yang ikut; catat komentar warga. Kalau sampah liar berkurang & minimal 3 keluarga aktif, ide layak diperluas."},
];
